import{_ as o,o as a,c as d,ai as r}from"./chunks/framework.scx6l_IK.js";const p=JSON.parse('{"title":"如何面对焦虑","description":"","frontmatter":{},"headers":[],"relativePath":"20-专题研究/topic-焦虑.md","filePath":"20-专题研究/topic-焦虑.md","lastUpdated":1778333830000}'),u={name:"20-专题研究/topic-焦虑.md"};function e(n,t,l,s,q,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="如何面对焦虑" tabindex="-1">如何面对焦虑 <a class="header-anchor" href="#如何面对焦虑" aria-label="Permalink to &quot;如何面对焦虑&quot;">​</a></h1><blockquote><p>专题分析：焦虑的根源与化解之道 组合模型：对境不住 + 自然务实 + 对法不执 分级阅读：⚡ 速用 · 📖 标准 · 🔍 深入</p></blockquote><hr><h2 id="⚡-速用版-焦虑三步急救法" tabindex="-1">⚡ 速用版：焦虑三步急救法 <a class="header-anchor" href="#⚡-速用版-焦虑三步急救法" aria-label="Permalink to &quot;⚡ 速用版：焦虑三步急救法&quot;">​</a></h2><p>焦虑最痛苦的不是事情本身，是事情还没发生，心已经被&quot;想象的灾难&quot;带跑了。下次焦虑时，按这三步走：</p><p><strong>① 觉察（对境不住）</strong>——问自己：&quot;我在焦虑什么？把那个具体的事说出来。&quot;</p><blockquote><p>未来还没有来，你焦虑的是一个不存在的东西。</p></blockquote><p><strong>② 行动（自然务实）</strong>——把焦虑拆成你今天能做的具体步骤。</p><blockquote><p>担心考试→今天看哪一章。担心汇报→今天准备哪一页。</p></blockquote><p><strong>③ 放下（对法不执）</strong>——做了就不纠结结果。&quot;因上精进，果上随缘。&quot;</p><blockquote><p>能做的做了，剩下的交给自然规律。</p></blockquote><hr><hr><h2 id="📖-一、焦虑的本质" tabindex="-1">📖 一、焦虑的本质 <a class="header-anchor" href="#📖-一、焦虑的本质" aria-label="Permalink to &quot;📖 一、焦虑的本质&quot;">​</a></h2><p>焦虑源于<strong>对未来的不确定性的执着</strong>。</p><blockquote><p><strong>&quot;过去心不可得，现在心不可得，未来心不可得。过去已成过去，未来还没有来，现在却不断地在流动。&quot;</strong></p><p>— <a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p></blockquote><p>从三个模型看焦虑的形成：</p><table tabindex="0"><thead><tr><th>模型角度</th><th>焦虑的成因</th><th>一句话</th></tr></thead><tbody><tr><td><strong>对境不住</strong></td><td>对&quot;未来情境&quot;的提前反应——事情还没发生，心已经被&quot;相&quot;带跑了</td><td>心在妄动</td></tr><tr><td><strong>自然务实</strong></td><td>想得太多，做得太少——焦虑积在脑子里，没有流到手脚上</td><td>行跟不上想</td></tr><tr><td><strong>对法不执</strong></td><td>非要某个结果才安心——对&quot;必须怎样&quot;的执着</td><td>放不下结果</td></tr></tbody></table><blockquote><p>🔍 <strong>术语边界辨析</strong>：本专题中&quot;焦虑&quot;&quot;烦恼&quot;&quot;恐惧&quot;&quot;执着&quot;几个词交替出现——</p><ul><li><strong>烦恼</strong>：广义指一切困扰心绪的状态（&quot;一切烦恼为如来种&quot;），焦虑是烦恼的一种；了空居士在引用此句时用的是广义</li><li><strong>恐惧</strong>：了空居士答疑中较少区分&quot;恐惧&quot;与&quot;焦虑&quot;，通常都归为&quot;对境不住&quot;的反面——心被相带跑了</li><li><strong>执着</strong>：本专题中出现在三种语境——对未来的执着（三心不可得）、对结果的执着（因上精进果上随缘）、对评价的执着（四相）。三者实为同一&quot;执&quot;在不同面向的表现，根在&quot;我相&quot;未破</li><li>以下正文沿用日常用语习惯交替使用这些词，读者需知它们在体系中指向同一根源</li></ul></blockquote><hr><h2 id="📖-二、三种常见焦虑与对治" tabindex="-1">📖 二、三种常见焦虑与对治 <a class="header-anchor" href="#📖-二、三种常见焦虑与对治" aria-label="Permalink to &quot;📖 二、三种常见焦虑与对治&quot;">​</a></h2><h3 id="_1-对未来恐惧型焦虑" tabindex="-1">1. 对未来恐惧型焦虑 <a class="header-anchor" href="#_1-对未来恐惧型焦虑" aria-label="Permalink to &quot;1. 对未来恐惧型焦虑&quot;">​</a></h3><p>担心事情失败、健康出问题、失去。</p><blockquote><p><strong>&quot;过去心不可得，现在心不可得，未来心不可得。&quot;</strong></p><p>— <a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p></blockquote><p>未来还没有来，你在焦虑一个不存在的东西。该做的准备去做，不该担心的不要提前透支情绪。</p><p><strong>模型应用</strong>：</p><ul><li>对境不住：觉察&quot;我在担心一个还没发生的未来&quot;——把心拉回当下</li><li>自然务实：把&quot;万一……&quot;的恐惧转化为具体的预防措施</li><li>对法不执：做了准备就放下，结果不是你能完全控制的</li></ul><h3 id="_2-对选择的焦虑" tabindex="-1">2. 对选择的焦虑 <a class="header-anchor" href="#_2-对选择的焦虑" aria-label="Permalink to &quot;2. 对选择的焦虑&quot;">​</a></h3><p>纠结于选A还是选B，怕选错。</p><blockquote><p><strong>&quot;因上精进，果上随缘就是中观。&quot;</strong></p><p>— <a href="/60-原文段落/道德经14章-因上精进果上随缘">道德经14章-因上精进果上随缘</a></p></blockquote><blockquote><p><strong>&quot;经验也只能参考，不能教条主义。&quot;</strong></p><p>— <a href="/60-原文段落/道德经64章-经验不能教条主义">道德经64章-经验不能教条主义</a></p></blockquote><p>收集足够信息，做出当下最合理的决定，然后<strong>做就做了，不要回头纠结</strong>。没有绝对正确的选择，只有当下最适合的选择。</p><p><strong>模型应用</strong>：</p><ul><li>对境不住：把&quot;怕选错&quot;的恐惧和&quot;做选择&quot;本身分开——恐惧是相，选择是事</li><li>自然务实：抓核心——哪个选项更符合你的长期目标？而不是无限比较细节</li><li>对法不执：选了就选了，不回头。缘起性空——一切不永恒，选错了也能修正</li></ul><h3 id="_3-对评价的焦虑" tabindex="-1">3. 对评价的焦虑 <a class="header-anchor" href="#_3-对评价的焦虑" aria-label="Permalink to &quot;3. 对评价的焦虑&quot;">​</a></h3><p>怕被人看不起、怕做不好被人说。</p><blockquote><p><strong>&quot;若菩萨有我相、人相、众生相、寿者相，即非菩萨。&quot;</strong></p><p>— <a href="/60-原文段落/金刚经3分-四相与无我">金刚经3分-四相与无我</a></p></blockquote><p>太在意别人的评价，是因为还有&quot;我相&quot;——我在别人心中是什么形象？放下这个&quot;我&quot;，就没有人需要评价我了。</p><p><strong>模型应用</strong>：</p><ul><li>对境不住：&quot;凡所有相皆是虚妄&quot;——别人的评价也是一个&quot;相&quot;，会变化的</li><li>自然务实：把&quot;别人怎么看我&quot;换成&quot;我该做什么&quot;——回到事情本身</li><li>对法不执：连&quot;我在修行&quot;的相都要放下，何况&quot;我在别人心中的形象&quot;</li></ul><blockquote><p>📝 <strong>分类说明</strong>：以上三种焦虑分类（未来恐惧型、选择型、评价型）是笔者对了空居士答疑中常见提问类型的归纳，并非了空居士本人的分类。在了空居士看来，所有焦虑的根源都是&quot;对境不住&quot;——重点不在于&quot;属于哪一型&quot;,而在于&quot;觉察到的那一刻&quot;。</p></blockquote><hr><h2 id="📖-三、模型协同-三步闭环" tabindex="-1">📖 三、模型协同：三步闭环 <a class="header-anchor" href="#📖-三、模型协同-三步闭环" aria-label="Permalink to &quot;📖 三、模型协同：三步闭环&quot;">​</a></h2><p>焦虑专题的三种模型不是并列关系，而是<strong>一个操作流程的三个环节</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  对境不住              自然务实              对法不执</span></span>
<span class="line"><span>  ─────────             ─────────             ─────────</span></span>
<span class="line"><span>  止 损                 行 动                 放 下</span></span>
<span class="line"><span>  把心从&quot;未来&quot;拉回      把焦虑拆成可做的      做了就不纠结</span></span>
<span class="line"><span>  当下                  具体步骤              结果</span></span></code></pre></div><p><strong>它们为什么是闭环？</strong></p><p>焦虑的典型过程是：<strong>灾难想象 → 情绪积压 → 更不敢行动 → 更多灾难想象</strong>——恶性循环。</p><p>三个模型恰好对应这个循环的<strong>三个破解点</strong>：</p><table tabindex="0"><thead><tr><th>环节</th><th>模型</th><th>做什么</th><th>如果跳过会怎样</th></tr></thead><tbody><tr><td>① 止损</td><td>对境不住</td><td>&quot;三心不可得&quot;——先把心从未来的灾难画面中拉出来</td><td>心静不下来，行动是慌乱的</td></tr><tr><td>② 行动</td><td>自然务实</td><td>&quot;做就是了&quot;——把焦虑拆成具体步骤，做最小的第一步</td><td>停在觉察阶段，变成&quot;我知道我在焦虑但不知道怎么办&quot;</td></tr><tr><td>③ 放下</td><td>对法不执</td><td>&quot;因上精进果上随缘&quot;——做了就放下</td><td>做了但放不下结果，做完更焦虑</td></tr></tbody></table><blockquote><p>🔍 <strong>进阶理解</strong>：这个三步闭环不只适用于焦虑。情绪、选择、工作修行等专题都隐含这个结构。底层逻辑是——&quot;住&quot;（停下来不乱动）+ &quot;行&quot;（做该做的事）+ &quot;舍&quot;（不执着结果）——三者的平衡。</p></blockquote><hr><h2 id="📖-四、案例拆解" tabindex="-1">📖 四、案例拆解 <a class="header-anchor" href="#📖-四、案例拆解" aria-label="Permalink to &quot;📖 四、案例拆解&quot;">​</a></h2><blockquote><p>📝 <strong>说明</strong>：以下案例为基于典型场景的假设性推演，用于展示三步闭环的应用方式，并非了空居士原文记载的真实案例。</p></blockquote><h3 id="案例一-工作汇报焦虑" tabindex="-1">案例一：工作汇报焦虑 <a class="header-anchor" href="#案例一-工作汇报焦虑" aria-label="Permalink to &quot;案例一：工作汇报焦虑&quot;">​</a></h3><p><strong>场景</strong>：周一要向上级做季度汇报，数据还没整理完，领导是出了名的严格。周日晚上翻来覆去睡不着，脑子里反复演&quot;领导皱眉质问&quot;的画面。</p><p><strong>❌ 没有模型介入的常见反应</strong>：</p><ul><li>刷手机到凌晨——逃避，但焦虑感更强</li><li>强迫自己继续整理数据——但手在动心在慌，效率很低</li><li>越想越气：&quot;公司制度有问题&quot;——把焦虑转化成抱怨</li></ul><p><strong>✅ 三步闭环介入</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>模型</th><th>做什么</th><th>内心对白</th></tr></thead><tbody><tr><td>①</td><td>对境不住</td><td>觉察&quot;我在焦虑周一汇报&quot;——把那个具体的恐惧说出来</td><td>&quot;我现在害怕的是汇报时被批评的画面——但这个画面还没发生。&quot;</td></tr><tr><td>②</td><td>自然务实</td><td>问自己：&quot;现在能做什么？&quot;</td><td>&quot;今晚把数据框架搭好，明天早上一小时填数据。能做多少做多少。&quot;</td></tr><tr><td>③</td><td>对法不执</td><td>做完放下，去睡觉</td><td>&quot;能做的准备已经做了。结果不是我能完全控制的。睡。&quot;</td></tr></tbody></table><p><strong>结果</strong>：周一汇报虽然领导确实问了几条数据，但因为没有带着&quot;完蛋了&quot;的恐惧，回答反而更从容。</p><h3 id="案例二-社交焦虑" tabindex="-1">案例二：社交焦虑 <a class="header-anchor" href="#案例二-社交焦虑" aria-label="Permalink to &quot;案例二：社交焦虑&quot;">​</a></h3><p><strong>场景</strong>：周末要参加大学同学聚会。毕业后发展不太顺利，想到别人可能都混得很好，怕被问&quot;现在做什么&quot;、怕被比下去。已经在想要不要找个理由不去了。</p><p><strong>❌ 没有模型介入的常见反应</strong>：</p><ul><li>找借口不去——短时间舒服了，但长期更焦虑</li><li>去了全程紧张——怕被问，躲着人说话，回来更难受</li><li>提前准备一堆&quot;话术&quot;——但越准备越紧张</li></ul><p><strong>✅ 三步闭环介入</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>模型</th><th>做什么</th><th>内心对白</th></tr></thead><tbody><tr><td>①</td><td>对境不住</td><td>&quot;四相与无我&quot;——看到&quot;我相&quot;在作祟</td><td>&quot;哦，我害怕的其实是&#39;怕被人比下去&#39;——这是我的&#39;我相&#39;在疼。&quot;</td></tr><tr><td>②</td><td>自然务实</td><td>把目的从&quot;不被比下去&quot;换成&quot;见见老同学&quot;</td><td>&quot;去了，见到谁聊谁。不问业绩，聊聊最近在做什么有趣的事。&quot;</td></tr><tr><td>③</td><td>对法不执</td><td>去了就去了，不管表现如何</td><td>&quot;聚会只是一次碰面，不是考试。没有人真的在打分。&quot;</td></tr></tbody></table><p><strong>结果</strong>：去了发现其实大家各有各的烦恼——混得好的也有压力。真正让一个人显得不自在的，不是&quot;混得好不好&quot;，是全程紧绷的防御状态。</p><blockquote><p>🔍 <strong>案例共性</strong>：两个案例中，焦虑的根都是<strong>心先于事实跑了</strong>。三步闭环的本质不是&quot;解决问题&quot;（问题还没发生），是<strong>先让心回来，再谈行动</strong>。这了空居士叫&quot;保持平静的要诀&quot;。</p></blockquote><hr><h2 id="📖-五、常见误区" tabindex="-1">📖 五、常见误区 <a class="header-anchor" href="#📖-五、常见误区" aria-label="Permalink to &quot;📖 五、常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th><th>原文依据</th></tr></thead><tbody><tr><td>焦虑就是软弱</td><td>焦虑是心对未来&quot;相&quot;的执着，人人都有</td><td><a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></td></tr><tr><td>要完全消除焦虑才能修行</td><td>&quot;即得不等于得后&quot;——带着焦虑修，修着修着焦虑就淡了</td><td>—</td></tr><tr><td>想得多才能不焦虑</td><td>焦虑的反面是行动，不是过度分析</td><td>—</td></tr><tr><td>不焦虑就是不在乎</td><td>对境不住是&quot;知道但不被带走&quot;，不是麻木</td><td><a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></td></tr><tr><td>有焦虑说明修行没效果</td><td>&quot;烦恼即菩提&quot;——看到焦虑的那一刻，就是修行的开始</td><td><a href="/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></td></tr></tbody></table><hr><h2 id="🔍-六、理论边界与内在张力-深入版" tabindex="-1">🔍 六、理论边界与内在张力（深入版） <a class="header-anchor" href="#🔍-六、理论边界与内在张力-深入版" aria-label="Permalink to &quot;🔍 六、理论边界与内在张力（深入版）&quot;">​</a></h2><blockquote><p>研究者视角——以下讨论不降低本专题的实用价值，但为深度理解提供必要的批判性框架。</p></blockquote><h3 id="适用边界" tabindex="-1">适用边界 <a class="header-anchor" href="#适用边界" aria-label="Permalink to &quot;适用边界&quot;">​</a></h3><ul><li><strong>日常焦虑 vs 临床焦虑障碍</strong>：了空居士的方法针对的是&quot;正常人面对生活变化时的焦虑反应&quot;。如果是临床意义上的焦虑症（持续超过6个月、严重影响日常生活、伴有心悸/失眠等躯体症状），建议同时寻求专业医疗帮助。三步急救法是心法辅助，不能替代专业治疗。</li><li><strong>认知前提</strong>：三步急救法建立在&quot;认知能力正常、有基本自我觉察能力&quot;的前提上。在极端恐慌发作时，第一步&quot;觉察&quot;本身就很难做到——这时需要先通过深呼吸、身体活动等方式降低唤醒水平，再启动三步法。</li></ul><h3 id="体系内的模型张力" tabindex="-1">体系内的模型张力 <a class="header-anchor" href="#体系内的模型张力" aria-label="Permalink to &quot;体系内的模型张力&quot;">​</a></h3><p>完整的了空居士体系包含7个模型，不同模型在焦虑场景下可能给出不同的操作指引：</p><table tabindex="0"><thead><tr><th>张力点</th><th>三步法建议</th><th>另一模型视角</th><th>如何协调</th></tr></thead><tbody><tr><td>行动 vs 静坐</td><td>自然务实：焦虑就行动</td><td>性命双修：静坐观情绪</td><td>不是矛盾，是阶梯——焦虑唤醒水平高时先行动释放能量；唤醒水平可控时静坐直接观。按当下状态选</td></tr><tr><td>止损 vs 压抑</td><td>对境不住：止损</td><td>—</td><td>止损不是压抑。区别在于&quot;觉察&quot;——止损有觉察（&quot;我知道我在焦虑&quot;），压抑无觉察（&quot;我不应该焦虑&quot;）。前者开放，后者对抗</td></tr><tr><td>放下 vs 忽视</td><td>对法不执：放下结果</td><td>—</td><td>三步法中&quot;放下&quot;的前提是第二步&quot;行动&quot;已完成。没做就谈放下，是逃避不是修行</td></tr></tbody></table><h3 id="方法论局限" tabindex="-1">方法论局限 <a class="header-anchor" href="#方法论局限" aria-label="Permalink to &quot;方法论局限&quot;">​</a></h3><ul><li><strong>推演案例的可信度</strong>：案例为基于典型场景的假设性推演，不是了空居士原文记载的真实案例。它们展示的是&quot;理想路径&quot;，真实情境中可能因个人根器、环境限制而走不通。了空居士反复强调&quot;解不开的诚心请教别人&quot;——意即有些困境需要师友指点，不是靠一己之力读完一篇专题就能解决的。</li><li><strong>从&quot;对话&quot;到&quot;文本&quot;的衰减</strong>：了空居士的教导本是通过面对面答疑、针对具体人具体问题展开的。将其整理为书面专题，必然损失&quot;应机施教&quot;的活力和精确性。本专题是&quot;地图&quot;，不是&quot;实地&quot;——读懂了不等于做到了。</li></ul><hr><h2 id="🔍-七、模型原子在焦虑中的应用-深入版" tabindex="-1">🔍 七、模型原子在焦虑中的应用（深入版） <a class="header-anchor" href="#🔍-七、模型原子在焦虑中的应用-深入版" aria-label="Permalink to &quot;🔍 七、模型原子在焦虑中的应用（深入版）&quot;">​</a></h2><blockquote><p>以下是模型中与焦虑直接相关的关键原子及其应用。当你熟悉三步闭环后，可以用这些原子更精细地拆解焦虑。</p></blockquote><table tabindex="0"><thead><tr><th>模型原子</th><th>原文</th><th>焦虑中的应用</th></tr></thead><tbody><tr><td><strong>三心不可得</strong></td><td>&quot;过去心不可得，现在心不可得，未来心不可得&quot;</td><td>焦虑的未来还没来——你在焦虑一个不存在的&quot;相&quot;。直接用这个原子破</td></tr><tr><td><strong>离相即客观</strong></td><td>&quot;若见诸相非相，即见如来&quot;</td><td>把&quot;灾难画面&quot;看成一个相——它存在（在你的脑子里），但不是事实</td></tr><tr><td><strong>理智</strong></td><td>&quot;保持平静的要诀就是保持理智&quot;</td><td>焦虑时情绪占主导，理智被淹没了。问&quot;我为什么不平静&quot;就是启动理智</td></tr><tr><td><strong>因上精进果上随缘</strong></td><td>&quot;因上精进，果上随缘就是中观&quot;</td><td>把&quot;担心结果&quot;转化为&quot;做好每一步&quot;。这是从焦虑到行动的转化开关</td></tr><tr><td><strong>攀缘vs随缘</strong></td><td>&quot;攀缘是一厢情愿的主观追求&quot;</td><td>焦虑的本质就是攀缘——用想象中的结果折磨现在的自己</td></tr><tr><td><strong>法尚应舍</strong></td><td>&quot;法尚应舍，何况非法&quot;</td><td>连&quot;我不能焦虑&quot;这个念头都要放下。越对抗焦虑越焦虑</td></tr><tr><td><strong>烦恼即菩提</strong></td><td>&quot;一切烦恼为如来种&quot;</td><td>焦虑不是敌人。你觉察到焦虑的那个瞬间，就是修行的进步</td></tr></tbody></table><hr><h2 id="🔍-专题地图" tabindex="-1">🔍 专题地图 <a class="header-anchor" href="#🔍-专题地图" aria-label="Permalink to &quot;🔍 专题地图&quot;">​</a></h2><h3 id="本专题在体系中的位置" tabindex="-1">本专题在体系中的位置 <a class="header-anchor" href="#本专题在体系中的位置" aria-label="Permalink to &quot;本专题在体系中的位置&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前置专题：[情绪] → 理解情绪管理的基础</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>本专题：  [焦虑] → 焦虑的根源与化解</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>进阶专题：[选择] → 焦虑常表现为&quot;怕选错&quot;</span></span>
<span class="line"><span>          [工作修行] → 工作中的焦虑转化为修行</span></span>
<span class="line"><span>          [疾病与健康] → 健康焦虑的处理</span></span></code></pre></div><h3 id="各层级读者阅读建议" tabindex="-1">各层级读者阅读建议 <a class="header-anchor" href="#各层级读者阅读建议" aria-label="Permalink to &quot;各层级读者阅读建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你是谁</th><th>读什么</th><th>目的</th></tr></thead><tbody><tr><td>现在就很焦虑</td><td>⚡ 速用版</td><td>马上能用</td></tr><tr><td>想系统了解焦虑的根</td><td>📖 标准版（全部）</td><td>理解+实践</td></tr><tr><td>想融会贯通佛学原理</td><td>🔍 深入版</td><td>理论深化</td></tr></tbody></table><h3 id="推荐模型" tabindex="-1">推荐模型 <a class="header-anchor" href="#推荐模型" aria-label="Permalink to &quot;推荐模型&quot;">​</a></h3><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 不被未来的&quot;相&quot;带跑（止损）</li><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 将焦虑转化为行动（行动）</li><li><a href="/10-核心模型/model-对法不执">对法不执</a> — 做了就放下（放下）</li><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 不执着绝对的好结果（补充）</li><li><a href="/10-核心模型/model-历境炼心">历境炼心</a> — 将焦虑视为修行的机会（进阶）</li></ul><h3 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h3><ul><li><a href="/50-概念资料/dict-烦恼">dict-烦恼</a> — 焦虑是烦恼的一种</li><li><a href="/50-概念资料/dict-平常心">dict-平常心</a> — 平常心是对治焦虑的日常状态</li><li><a href="/50-概念资料/dict-观照">dict-观照</a> — 观察焦虑的具体方法</li></ul><hr><blockquote><p>创建日期：2026-05-06 | 修订：2026-05-09（研究者视角升级：新增术语辨析、分类说明、理论边界与内在张力、案例证据标注） 素材来源分布：金刚经第3分（四相与无我）、第5分（离相/烦恼即菩提）、第10分（缘起性空/应无所住生心）、第18分（三心不可得），道德经第14章（因上精进果上随缘）、第64章（经验不能教条主义）。文中观点分析及分类归纳由笔者完成，不属了空居士原话。</p></blockquote>`,97)])])}const c=o(u,[["render",e]]);export{p as __pageData,c as default};
